CREATE TABLE "FACULTE" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nom" varchar UNIQUE NOT NULL,
  "code" varchar UNIQUE NOT NULL,
  "categorie" varchar NOT NULL
    CHECK ("categorie" IN ('faculte', 'ecole', 'institut')),
  "description" text,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "FILIERE" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nom" varchar NOT NULL,
  "code" varchar,
  "faculte_id" integer NOT NULL,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "NIVEAU" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nom" varchar NOT NULL,
  "ordre" integer NOT NULL,
  "filiere_id" integer NOT NULL
);

CREATE TABLE "SEMESTRE" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nom" varchar NOT NULL,
  "ordre" integer NOT NULL,
  "niveau_id" integer NOT NULL
);

CREATE TABLE "UE" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nom" varchar NOT NULL,
  "code" varchar,
  "aliases" text,
  "semestre_id" integer NOT NULL,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "ENSEIGNANT" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nom" varchar NOT NULL,
  "faculte_id" integer,
  "email" varchar,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "UTILISATEUR" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nom" varchar NOT NULL,
  "email" varchar UNIQUE NOT NULL,
  "mot_de_passe_hash" varchar NOT NULL,
  "avatar_url" varchar,
  "role" varchar NOT NULL DEFAULT 'etudiant',
  "statut" varchar NOT NULL DEFAULT 'actif',
  "faculte_id" integer,
  "filiere_id" integer,
  "niveau_id" integer,
  "email_verifie" boolean DEFAULT false,
  "points" integer DEFAULT 0,
  "date_inscription" timestamp DEFAULT (now()),
  "derniere_connexion" timestamp
);

CREATE TABLE "DOCUMENT" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "titre" varchar NOT NULL,
  "description" text,
  "type" varchar NOT NULL
    CHECK ("type" IN ('cours', 'annale', 'corrige', 'td', 'memoire', 'autre')),
  "ue_id" integer NOT NULL,
  "enseignant_id" integer,
  "annee_academique" varchar NOT NULL,
  "fichier_url" varchar NOT NULL,
  "format" varchar NOT NULL
    CHECK ("format" IN ('pdf', 'docx', 'pptx', 'image')),
  "taille_ko" integer NOT NULL,
  "nb_pages" integer,
  "langue" varchar DEFAULT 'fr',
  "uploader_id" integer NOT NULL,
  "statut" varchar NOT NULL DEFAULT 'en_attente',
  "nb_vues" integer DEFAULT 0,
  "nb_telechargements" integer DEFAULT 0,
  "note_moyenne" decimal(3,2) DEFAULT 0,
  "date_upload" timestamp DEFAULT (now()),
  "date_mise_a_jour" timestamp DEFAULT (now())
);

CREATE TABLE "TAG" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nom" varchar UNIQUE NOT NULL,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "DOCUMENT_TAG" (
  "document_id" integer NOT NULL,
  "tag_id" integer NOT NULL,
  PRIMARY KEY ("document_id", "tag_id")
);

CREATE TABLE "VERSION_DOCUMENT" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "document_id" integer NOT NULL,
  "fichier_url" varchar NOT NULL,
  "taille_ko" integer,
  "commentaire" varchar,
  "uploade_par" integer,
  "date_version" timestamp DEFAULT (now())
);

CREATE TABLE "NOTATION" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "document_id" integer NOT NULL,
  "utilisateur_id" integer NOT NULL,
  "note" integer NOT NULL,
  "commentaire" text,
  "date_notation" timestamp DEFAULT (now())
);

CREATE TABLE "COMMENTAIRE" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "document_id" integer NOT NULL,
  "utilisateur_id" integer NOT NULL,
  "parent_id" integer,
  "contenu" text NOT NULL,
  "statut" varchar DEFAULT 'visible',
  "date_commentaire" timestamp DEFAULT (now())
);

CREATE TABLE "FAVORI" (
  "utilisateur_id" integer NOT NULL,
  "document_id" integer NOT NULL,
  "date_ajout" timestamp DEFAULT (now()),
  PRIMARY KEY ("utilisateur_id", "document_id")
);

CREATE TABLE "TELECHARGEMENT" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "document_id" integer NOT NULL,
  "utilisateur_id" integer,
  "date_telechargement" timestamp DEFAULT (now()),
  "ip" varchar
);

CREATE TABLE "SIGNALEMENT" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "document_id" integer NOT NULL,
  "signaleur_id" integer NOT NULL,
  "motif" varchar NOT NULL
    CHECK ("motif" IN ('contenu_illegal', 'erreur', 'doublon', 'qualite', 'droit_auteur', 'autre')),
  "commentaire" text,
  "statut" varchar NOT NULL DEFAULT 'ouvert'
    CHECK ("statut" IN ('ouvert', 'en_cours', 'traite', 'rejete')),
  "traite_par" integer,
  "date_signalement" timestamp DEFAULT (now()),
  "date_traitement" timestamp
);

CREATE TABLE "MODERATION_ACTION" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "moderateur_id" integer NOT NULL,
  "document_id" integer,
  "utilisateur_cible_id" integer,
  "action" varchar NOT NULL
    CHECK ("action" IN ('valider', 'retirer', 'avertir', 'suspendre', 'bannir')),
  "raison" text,
  "date_action" timestamp DEFAULT (now())
);

CREATE TABLE "JOURNAL_AUDIT" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "utilisateur_id" integer,
  "action" varchar NOT NULL,
  "cible_type" varchar,
  "cible_id" integer,
  "details" text,
  "ip" varchar,
  "date_action" timestamp DEFAULT (now())
);

CREATE TABLE "BADGE" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nom" varchar UNIQUE NOT NULL,
  "description" text,
  "icone_url" varchar,
  "condition_type" varchar NOT NULL,
  "condition_valeur" integer,
  "points_recompense" integer DEFAULT 0,
  "actif" boolean DEFAULT true,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "UTILISATEUR_BADGE" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "utilisateur_id" integer NOT NULL,
  "badge_id" integer NOT NULL,
  "date_obtention" timestamp DEFAULT (now()),
  "attribue_par" integer
);

CREATE TABLE "HISTORIQUE_POINTS" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "utilisateur_id" integer NOT NULL,
  "points" integer NOT NULL,
  "raison" varchar NOT NULL,
  "reference_type" varchar,
  "reference_id" integer,
  "date_ajout" timestamp DEFAULT (now())
);

CREATE TABLE "NOTIFICATION" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "utilisateur_id" integer NOT NULL,
  "type" varchar NOT NULL,
  "titre" varchar NOT NULL,
  "message" text,
  "lien" varchar,
  "lue" boolean DEFAULT false,
  "date_creation" timestamp DEFAULT (now())
);

CREATE UNIQUE INDEX ON "FILIERE" ("nom", "faculte_id");

CREATE UNIQUE INDEX ON "UE" ("nom", "semestre_id");

CREATE UNIQUE INDEX ON "NOTATION" ("document_id", "utilisateur_id");

CREATE UNIQUE INDEX ON "UTILISATEUR_BADGE" ("utilisateur_id", "badge_id");

